// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(value <= address(this).balance);
        vm.assume(target != address(0) && target != address(c));
        address owner = c.owner();
        vm.deal(owner, value);
        vm.prank(owner);
        c.sendMoney(target, value);
        address nonOwner = address(0x1234);
        vm.assume(nonOwner != owner);
        vm.prank(nonOwner);
        uint256 balanceBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceAfter = address(c).balance;
        assertTrue(reverted && balanceAfter == balanceBefore);
    }
}
